fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            let mut lines = Vec::new();
            let mut start = 0;
            let bytes = s.as_bytes();
            let len = s.len();

            for (i, &b) in bytes.iter().enumerate() {
                if b == b'\n' {
                    // Include '\n' if keepends is true,
                    // otherwise exclude it.
                    let end = if keepends { i + 1 } else { i };
                    if start < end {
                        lines.push(s[start..end].to_string());
                    } else {
                        // Empty line (e.g., consecutive \n), push empty string
                        lines.push(String::new());
                    }
                    start = i + 1;
                } else if b == b'\r' {
                    // Handle possible CRLF
                    if i + 1 < len && bytes[i + 1] == b'\n' {
                        let end = if keepends { i + 2 } else { i };
                        if start < end {
                            lines.push(s[start..end].to_string());
                        } else {
                            lines.push(String::new());
                        }
                        start = i + 2;
                    } else {
                        // Lone CR line ending
                        let end = if keepends { i + 1 } else { i };
                        if start < end {
                            lines.push(s[start..end].to_string());
                        } else {
                            lines.push(String::new());
                        }
                        start = i + 1;
                    }
                }
            }
            // Add remaining segment after last line ending (or whole string if no line endings)
            if start < len {
                lines.push(s[start..].to_string());
            } else if lines.is_empty() {
                // String is empty or ends exactly on line endings, ensure at least one element
                lines.push(String::new());
            }

            // Guarantee that this inner list is non-empty even if original string was empty
            if lines.is_empty() {
                lines.push(String::new());
            }

            lines
        })
        .collect()
}